/// <reference types="../types/react-table-config" />

import React, { ReactNode, useMemo } from 'react';
import { isElement } from 'react-is';

import { CellActions } from '../plugins/use-user-actions/components/CellActions.js';
import { ColumnActions } from '../plugins/use-user-actions/components/ColumnActions.js';
import { RowActions } from '../plugins/use-user-actions/components/RowActions.js';
import type {
  CellActionsProvider,
  ColumnActionsProvider,
  RowActionsProvider,
  UserActionConfig,
} from '../plugins/use-user-actions/useUserActions.types.js';

/** Extracts configured user action slots from DataTable.UserActions node. */
export function useUserActionConfig(userActions: ReactNode): UserActionConfig {
  return useMemo(() => {
    const config: UserActionConfig = {
      defaultColumnActionProvider: null,
      columnActionProviders: {},
      defaultCellActionProvider: null,
      cellActionProviders: {},
      rowActionsProvider: null,
    };

    if (!isElement(userActions)) {
      return config;
    }

    React.Children.forEach(userActions.props.children, (child) => {
      if (isElement(child)) {
        switch (child.type) {
          case CellActions: {
            const { column: columnName, children: userActionsProvider } =
              child.props;
            handleCellActions(columnName, userActionsProvider, config);
            break;
          }
          case ColumnActions: {
            const { column: columnName, children: userActionsProvider } =
              child.props;
            handleColumnActions(columnName, userActionsProvider, config);
            break;
          }
          case RowActions: {
            const { children: userActionsProvider } = child.props;
            handleRowActions(userActionsProvider, config);
            break;
          }
        }
      }
    });

    return config;
  }, [userActions]);
}

function handleCellActions(
  columnName: string | null,
  cellActionsProvider: CellActionsProvider,
  config: UserActionConfig,
): void {
  if (typeof cellActionsProvider !== 'function') {
    // eslint-disable-next-line no-console
    console.warn(
      columnName
        ? `CellActions provider for column '${columnName}' is not a function!`
        : 'Default CellActions provider is not a function!',
    );
    return;
  }

  if (columnName) {
    config.cellActionProviders[columnName] = cellActionsProvider;
  } else {
    config.defaultCellActionProvider = cellActionsProvider;
  }
}

function handleColumnActions(
  columnName: string | null,
  columnActionsProvider: ColumnActionsProvider,
  config: UserActionConfig,
): void {
  if (typeof columnActionsProvider !== 'function') {
    // eslint-disable-next-line no-console
    console.warn(
      columnName
        ? `ColumnActions provider for column '${columnName}' is not a function!`
        : 'Default ColumnActions provider is not a function!',
    );
    return;
  }

  if (columnName) {
    config.columnActionProviders[columnName] = columnActionsProvider;
  } else {
    config.defaultColumnActionProvider = columnActionsProvider;
  }
}

function handleRowActions(
  rowActionsProvider: RowActionsProvider,
  config: UserActionConfig,
): void {
  if (typeof rowActionsProvider !== 'function') {
    // eslint-disable-next-line no-console
    console.warn('RowActions provider is not a function!');
    return;
  }

  config.rowActionsProvider = rowActionsProvider;
}
